<script setup>import {computed} from 'vue';const props=defineProps({values:Array});const max=computed(()=>Math.max(1,...props.values.map(v=>v.minutes)))</script><template><div class="chart"><div v-for="day in values" :key="day.label" class="bar-column"><small>{{day.minutes}}m</small><div class="bar-space"><div class="bar" :style="{height:Math.max(5,day.minutes/max*100)+'%'}"></div></div><span>{{day.label}}</span></div></div></template>